#include <stdio.h>
#define vector_asc_debug_printf(...) printf(__VA_ARGS__)
#else
#define vector_asc_debug_printf(...) (void)0
#endif

#define ASC_MAGIC "date"
#define VECTOR_ASC_MAX_LINE_SIZE 512
/* Columns are separated by spaces or tabs; also drop the line ending */
#define VECTOR_ASC_DELIMITERS " \t\r\n"

/* Anchored, so that the first column is the time stamp, and the channel
 * column is a channel number or CANFD */
static const gchar *packet_pattern = "^\\s*\\d+\\.\\d+\\s+(\\d+\\s+(\\w+\\s+(Tx|Rx)|ErrorFrame)|CANFD)";
static const gchar *base_pattern = "base\\s+(hex|dec)(\\s+timestamps\\s+(absolute|relative))?";

typedef enum {
  TimeStamp,
  Channel,
  CanID,
  Direction,
  Brs,
  Esi,
  DataMarker,
  Dlc,
  DataLength,
  DataBytes
} vector_asc_data_column_t;

typedef enum{
  Hex,
  Dec
} vector_asc_base_t;

typedef enum{
  Absolute,
  Relative
} vector_asc_timestamp_t;

typedef enum {
  Date,
  Base,
  Version,
  Packets
} vector_asc_processing_state_t;

typedef struct {
  uint8_t major, minor, patch;
} vector_asc_version_t;

typedef struct {
  vector_asc_processing_state_t state;
  vector_asc_timestamp_t timestamps_type;
  vector_asc_base_t base;
  nstime_t trace_start;
  GRegex* data_matcher;
  vector_asc_version_t version;
} vector_asc_state_t;

static int vector_asc_file_type_subtype = -1;

static GRegex *month_regexes[16] = {0};
static const gchar *month_numbers[16] = {
    "01", "02", "03", "04", "05", "06", "07", "08",
    "09", "10", "11", "12", "03", "05", "10", "12"
};

static const gchar *month_patterns[16] = {
    "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug",
    "Sep", "Oct", "Nov", "Dec", "Mär", "Mai", "Okt", "Dez"
};

/* The month regexes are compiled once and kept for the life of the
 * program, as every heuristic open attempt may need them. */
static void init_month_regexes(void)
{
  static gsize initialized = 0;

  if (g_once_init_enter(&initialized)) {
    for (int i = 0; i < 16; ++i) {
      month_regexes[i] = g_regex_new(month_patterns[i], 0, 0, NULL);
    }
    g_once_init_leave(&initialized, 1);
  }
}

void register_vector_asc(void);

/* Parse the date in the "date <WeekDay> <Month> <Date> <Fulltime> <Year>"
 * header line into the trace start time. */
static void
vector_asc_parse_date(vector_asc_state_t* state, const char* date_str)
{
  // replace month names with 2 digit numbers
  gchar *datetime_string = g_strdup(date_str);
  for (gsize i = 0; i < 16; i++) {
    GError *error = NULL;
    gchar *replaced = g_regex_replace_literal(
        month_regexes[i],
        datetime_string, -1, 0,
        month_numbers[i],
        0, &error
        );
    g_free(datetime_string);
    if (replaced == NULL) {
      // e.g. invalid UTF-8; leave the start time unparsed
      vector_asc_debug_printf("%s: Cannot parse date: %s\n", G_STRFUNC, error ? error->message : "");
      g_clear_error(&error);
      return;
    }
    datetime_string = replaced;
  }
  // The month names are numbers now; skip the <WeekDay> name, if any
  // (python-can matches "date\s+\w+\s+").
  const char *date_fields = datetime_string;
  while (g_ascii_isspace(*date_fields))
    date_fields++;
  if (g_ascii_isalpha(*date_fields)) {
    while (*date_fields != '\0' && !g_ascii_isspace(*date_fields))
      date_fields++;
  }
  bool parsed = false;
  int year, month, day, hour, min, sec;
  char ampm[4];
  int sec_pos = 0;
  nstime_t sec_frac;
  const char *year_str;
  // Try the %m %d %H:%M:%S[.%f] %Y format. Starting with CANalyzer/CANoe
  // v8.2 SP2 the <Fulltime> is stored in milliseconds; parse the seconds
  // and their fraction like a Unix time.
  if (sscanf(date_fields, "%d %02d %02d:%02d:%n", &month, &day, &hour, &min, &sec_pos) == 4 &&
      sec_pos > 0 &&
      (year_str = unix_epoch_to_nstime(&sec_frac, &date_fields[sec_pos])) != NULL &&
      sec_frac.secs <= 60 &&
      sscanf(year_str, "%04d", &year) == 1) {
    sec = (int)sec_frac.secs;
    state->trace_start.nsecs = sec_frac.nsecs;
    parsed = true;
  }

  if (!parsed) {
    // try the 8 Apr 2025 3:49:52pm format
    int matches = sscanf(date_fields, "%d %02d %04d %d:%d:%d%02s", &day, &month, &year, &hour, &min, &sec, ampm);
    if (matches == 7) {
      // 12:xx am is 00:xx, and 12:xx pm is 12:xx
      if (hour == 12)
        hour = 0;
      if (g_ascii_strncasecmp(ampm, "pm", 2) == 0) {
        hour += 12;
      }
      parsed = true;
    }
  }

  if (parsed) {
    struct tm t = {0};
    t.tm_year = year - 1900;
    t.tm_mon = month - 1;
    t.tm_mday = day;
    t.tm_hour = hour;
    t.tm_min = min;
    t.tm_sec = sec;
    t.tm_isdst = -1;  // the date is local time; let mktime() find out about DST
    time_t start = mktime(&t);
    if (start != (time_t)-1)
      state->trace_start.secs = start;
    else
      state->trace_start.nsecs = 0;
  }

  g_free(datetime_string);
}

static wtap_open_return_val
vector_asc_parse(wtap* wth, vector_asc_state_t* state, gint64* offset, int* err, char** err_info)
{
  gint64 seek_off = 0;
  char line_buffer[VECTOR_ASC_MAX_LINE_SIZE];

  vector_asc_debug_printf("%s: Trying vector_asc file decoder\n", G_STRFUNC);

  /* Initial start time until we find it in the header */
  state->trace_start.secs = time(NULL);
  state->trace_start.nsecs = 0;
  state->state = Date;
  state->timestamps_type = Absolute;

  /* Bail if the end of the file is here and it hasn't been determined it's a Vector ASC file */
  while (!file_eof(wth->fh))
  {
    seek_off = file_tell(wth->fh);
    vector_asc_debug_printf("%s: Starting parser at offset %" PRIi64 "\n", G_STRFUNC, seek_off);

    if (file_gets(line_buffer, VECTOR_ASC_MAX_LINE_SIZE, wth->fh) == NULL)
    {
      /* Error reading file, bail out */
      *err = file_error(wth->fh, err_info);
      if (*err != 0 && *err != WTAP_ERR_SHORT_READ)
        return WTAP_OPEN_ERROR;

      return WTAP_OPEN_NOT_MINE;
    }

    g_strstrip(line_buffer);
    size_t line_len = strlen(line_buffer);

    /* Ignore empty lines */
    if (line_len == 0)
      continue;

    switch (state->state) {
      case Date:
        if (strncmp(line_buffer, ASC_MAGIC, strlen(ASC_MAGIC)) != 0) {
          return WTAP_OPEN_NOT_MINE;
        }
        // the line may be just "date", so don't index past its end
        vector_asc_parse_date(state, &line_buffer[strlen(ASC_MAGIC)]);
        state->state = Base;
        break;
      case Base:
        if (g_ascii_strncasecmp(line_buffer, "base ", 5) == 0) {
          GMatchInfo *match_info;
          GRegex *base_regex = g_regex_new(base_pattern, G_REGEX_CASELESS, 0, NULL);
          if (g_regex_match(base_regex, line_buffer, 0, &match_info)) {
            const gchar *base_str = g_match_info_fetch(match_info, 1);
            const gchar *time_str = g_match_info_fetch(match_info, 3);

            if (g_ascii_strcasecmp(base_str, "hex") == 0)
              state->base = Hex;
            else
              state->base = Dec;

            if (time_str && g_ascii_strcasecmp(time_str, "relative") == 0) {
              state->timestamps_type = Relative;
            }

            g_free((gchar *)base_str);
            g_free((gchar *)time_str);
          }

          g_match_info_free(match_info);
          g_regex_unref(base_regex);
          state->state = Version;
          break;
        }
        // The base line is expected after the date; like python-can, accept
        // a file without one, and process the line as the next header line
        // or a packet.
        state->state = Version;
        /* FALLTHROUGH */
      case Version:
        // The base line is followed by "internal events logged" or
        // "no internal events logged", and starting with CANalyzer/CANoe v7.0
        // a version number is written after the header in form of a comment:
        // '// version <major>.<minor>.<patch>'
        if (strncmp(line_buffer, "// version", 10) == 0 ||
            g_ascii_strcasecmp(line_buffer, "internal events logged") == 0 ||
            g_ascii_strcasecmp(line_buffer, "no internal events logged") == 0) {
          state->state = Packets;
          break;
        }
        // version not following the header, maybe pre 7.0 file -> reprocess the line as Packet
        state->state = Packets;
        /* FALLTHROUGH */
      case Packets:
        /* seek until the first data packet */
        if (state->data_matcher == NULL) {
          GError *error = NULL;
          state->data_matcher = g_regex_new(packet_pattern, (GRegexCompileFlags)(G_REGEX_OPTIMIZE | G_REGEX_RAW), (GRegexMatchFlags)0, &error);
          if (!state->data_matcher) {
            *err = WTAP_ERR_INTERNAL;
            *err_info = ws_strdup_printf("vector-asc: cannot compile the packet pattern: %s", error->message);
            g_error_free(error);
            return WTAP_OPEN_ERROR;
          }
        }

        if (g_regex_match(state->data_matcher, line_buffer, 0, NULL)) {
          *offset = seek_off;
          return WTAP_OPEN_MINE;
        }
        break;
    }
  }

  return WTAP_OPEN_NOT_MINE;
}

static bool vector_asc_process_classic_can_frame(char *token, wtap_can_msg_t *vector_msg, wtap* wth)
{
  vector_asc_state_t *state = (vector_asc_state_t*)wtap_socketcan_get_private_data(wth);
  if (g_ascii_strcasecmp(token, "ErrorFrame") == 0) {
    vector_msg->type = MSG_TYPE_ERR;
  } else {
    int columnIndex = CanID;
    int dataCounter = 0;
    uint32_t tmp = 0;
    while (token != NULL)
    {
      switch ((vector_asc_data_column_t)columnIndex) {
        case TimeStamp:
        case Channel:
          // just to make the compler warning free, timestamp and channel had been processed already in vector_asc_read_packet
          break ;
        case CanID:
          // extended frames marked by an x suffix in the CAN ID column
          if (state->base == Hex) {
            if (token[strlen(token) - 1] == 'x') {
              sscanf(token, "%Xx", &vector_msg->id);
              vector_msg->type = MSG_TYPE_EXT;
            } else {
              sscanf(token, "%X", &vector_msg->id);
              vector_msg->type = MSG_TYPE_STD;
            }
          } else {
            if (token[strlen(token) - 1] == 'x') {
              sscanf(token, "%ux", &vector_msg->id);
              vector_msg->type = MSG_TYPE_EXT;
            } else {
              sscanf(token, "%u", &vector_msg->id);
              vector_msg->type = MSG_TYPE_STD;
            }
          }
          columnIndex = Direction;
          break;
        case Direction:
          columnIndex = DataMarker;
          break;
        case DataMarker:
          if (token[0] == 'r') {
            vector_msg->type = MSG_TYPE_STD_RTR;
          }
          columnIndex = Dlc;
          break;
        case Dlc:
          sscanf(token, "%hhu", &vector_msg->data.length);
          columnIndex = DataBytes;
          break;
        case DataBytes:
          // databytes are generated into multiple columns
          if (dataCounter < 8 && dataCounter < vector_msg->data.length) {
            sscanf(token, "%02X", &tmp);
            vector_msg->data.data[dataCounter] = tmp;
          }
          dataCounter++;
          break;
        case Brs:
        case Esi:
        case DataLength:
          // CAN FD columns
          break;
      }
      token = strtok(NULL, VECTOR_ASC_DELIMITERS);
    }
  }
  return true;
}

static bool vector_asc_process_fd_can_frame(char *token, wtap_can_msg_t *vector_msg, wtap* wth)
{
  (void)wth;
  if (g_ascii_strcasecmp(token, "ErrorFrame") == 0) {
    vector_msg->type = MSG_TYPE_ERR;
  } else {
    int columnIndex = CanID;
    int dataCounter = 0;
    uint32_t tmp = 0;
    while (token != NULL)
    {
      switch ((vector_asc_data_column_t)columnIndex) {
        case TimeStamp:
        case Channel:
          // timestamp and channel had been processed already in vector_asc_read_packet
          break;
        case CanID:
          // extended frames marked by an x suffix in the CAN ID column
          //  CAN FD representation only in hex. (See 3.12 Symbols - <ID> -> special column
          if (token[strlen(token) - 1] == 'x') {
            sscanf(token, "%Xx", &vector_msg->id);
            vector_msg->type = MSG_TYPE_EXT_FD;
          } else {
            sscanf(token, "%X", &vector_msg->id);
            vector_msg->type = MSG_TYPE_STD_FD;
          }
          columnIndex = Direction;
          break;
        case Direction:
          columnIndex = DataMarker;
          break;
        case Brs:
          break;
        case Esi:
          break;
        case DataLength:
          break;
        case DataMarker:
          if (token[0] == 'r') {
            vector_msg->type = MSG_TYPE_STD_RTR;
          }
          columnIndex = Dlc;
          break;
        case Dlc:
          sscanf(token, "%hhu", &vector_msg->data.length);
          columnIndex = DataBytes;
          break;
        case DataBytes:
          if (dataCounter < 8 && dataCounter < vector_msg->data.length) {
            sscanf(token, "%02X", &tmp);
            vector_msg->data.data[dataCounter] = tmp;
          }
          dataCounter++;
          break;
      }
      token = strtok(NULL, VECTOR_ASC_DELIMITERS);
    }
  }
  /*
            can_id_str, frame_name_or_brs, rest_of_message = rest_of_message.split(
                None, 2
            )

            if frame_name_or_brs.isdigit():
                brs = frame_name_or_brs
                esi, dlc_str, data_length_str, data = rest_of_message.split(None, 3)
            else:
                brs, esi, dlc_str, data_length_str, data = rest_of_message.split(
                    None, 4
                )

            self._extract_can_id(can_id_str, msg_kwargs)
            msg_kwargs["bitrate_switch"] = brs == "1"
            msg_kwargs["error_state_indicator"] = esi == "1"
            dlc = int(dlc_str, self._converted_base)
            data_length = int(data_length_str)
            if data_length == 0:
                # CAN remote Frame
                msg_kwargs["is_remote_frame"] = True
                msg_kwargs["dlc"] = dlc
            else:
                if dlc2len(dlc) != data_length:
                    logger.warning(
                        "DLC vs Data Length mismatch %d[%d] != %d",
                        dlc,
                        dlc2len(dlc),
                        data_length,
                    )
                msg_kwargs["dlc"] = data_length

            self._process_data_string(data, data_length, msg_kwargs)

        return Message(**msg_kwargs)*/
  return true;
}

static bool
vector_asc_read_packet(wtap *wth, FILE_T fh, vector_asc_state_t* state,
                       wtap_rec *rec, int *err, gchar **err_info,
                       gint64 *data_offset)
{
  wtap_can_msg_t vector_msg = {0};
  char line_buffer[VECTOR_ASC_MAX_LINE_SIZE];

  while (!file_eof(fh))
  {
    if (data_offset)
      *data_offset = file_tell(fh);

    /* Read a line */
    if (file_gets(line_buffer, VECTOR_ASC_MAX_LINE_SIZE, fh) == NULL)
    {
      *err = file_error(fh, err_info);
      return false;
    }

    /* Skip the lines that are not CAN frames (Begin/End Triggerblock,
     * comments, events and other message types) instead of making an
     * empty record of them. */
    if (!g_regex_match(state->data_matcher, line_buffer, 0, NULL))
      continue;

    bool isFd = false;
    bool skip_line = false;

    memset(&vector_msg, 0, sizeof vector_msg);
    vector_msg.interface_id = WTAP_SOCKETCAN_INVALID_INTERFACE_ID;

    char *column = strtok(line_buffer, VECTOR_ASC_DELIMITERS);
    int columnIndex = TimeStamp;
    while (column != NULL && !skip_line)
    {
      switch ((vector_asc_data_column_t)columnIndex) {
        case TimeStamp:
          /* Seconds with a fraction; this fails (and the line is
           * skipped) if it does not fit in time_t. */
          if (unix_epoch_to_nstime(&vector_msg.ts, column) == NULL) {
            skip_line = true;
            break;
          }
          if (state->timestamps_type == Absolute) {
            /* saturates instead of overflowing */
            nstime_add(&vector_msg.ts, &state->trace_start);
          }
          columnIndex = Channel;
          break;
        case Channel:
          if ((strcmp(column, "Comment:") == 0) ||
              (strcmp(column, "GPS") == 0) ||
              (strcmp(column, "SV:") == 0) ||
              (strcmp(column, "log") == 0)) {
            /* Not a CAN frame */
            skip_line = true;
            break;
          }

          if (strcmp(column, "CANFD") == 0) {
            isFd = true;
            columnIndex = Channel;
          } else if (strcmp(column, "CAN") == 0) {
            columnIndex = Channel;
          } else {
            char* interface_name = wmem_strdup_printf(NULL, "interface%s", column);
            vector_msg.interface_id = wtap_socketcan_find_or_create_new_interface(wth, interface_name);
            wmem_free(NULL, interface_name);
            columnIndex = CanID;
          }
          break;
        case CanID:
          if (isFd) {
            vector_asc_process_fd_can_frame(column, &vector_msg, wth);
          } else {
            vector_asc_process_classic_can_frame(column, &vector_msg, wth);
          }
          break;
        default:
          break;
      }
      column = strtok(NULL, VECTOR_ASC_DELIMITERS);
    }

    if (skip_line)
      continue;

    return wtap_socketcan_gen_packet(wth, rec, &vector_msg, "vector-asc", err, err_info);
  }

  return false;
}

static bool
vector_asc_read(wtap   *wth, wtap_rec *rec, int *err, char **err_info,
                int64_t *data_offset)
{
  vector_asc_state_t* state = (vector_asc_state_t*)wtap_socketcan_get_private_data(wth);
  vector_asc_debug_printf("%s: Try reading at offset %" PRIi64 "\n", G_STRFUNC, file_tell(wth->fh));
  return vector_asc_read_packet(wth, wth->fh, state, rec, err, err_info, data_offset);
}

static bool vector_asc_seek_read(wtap *wth, int64_t seek_off, wtap_rec *rec, int *err, char **err_info)
{
  vector_asc_debug_printf("%s: Read at offset %" PRIi64 "\n", G_STRFUNC, seek_off);
  vector_asc_state_t* state = (vector_asc_state_t*)wtap_socketcan_get_private_data(wth);

  if (file_seek(wth->random_fh, seek_off, SEEK_SET, err) == -1)
  {
    *err      = errno;
    *err_info = g_strdup(g_strerror(errno));

    return false;
  }

  return vector_asc_read_packet(wth, wth->random_fh, state, rec, err, err_info, NULL);
}

static void
clean_asc_state(vector_asc_state_t* state)
{
  if (state != NULL)
  {
    if (state->data_matcher != NULL)
      g_regex_unref(state->data_matcher);

    g_free(state);
  }
}


static void vector_asc_close(void* tap_data)
{
  clean_asc_state((vector_asc_state_t*)tap_data);
}

wtap_open_return_val
vector_asc_open(wtap* wth, int* err, char** err_info)
{
  gint64 data_offset = 0;
  vector_asc_state_t* asc_state = g_new0(vector_asc_state_t, 1);

  /* wth->priv stores a pointer to the general file properties.
         * It it updated when the header data is parsed */
  wth->priv = asc_state;

  init_month_regexes();

  wtap_open_return_val open_val = vector_asc_parse(wth, asc_state, &data_offset, err, err_info);
  if (open_val != WTAP_OPEN_MINE)
  {
    clean_asc_state(asc_state);
    wth->priv = NULL;
    return open_val;
  }

  vector_asc_debug_printf("%s: This is our file\n", G_STRFUNC);

  /* Go to the start of the real packet data since header is now done */
  if (file_seek(wth->fh, data_offset, SEEK_SET, err) == -1)
  {
    *err = errno;
    *err_info = g_strdup(g_strerror(errno));
    return WTAP_OPEN_ERROR;
  }

  wtap_set_as_socketcan(wth, vector_asc_file_type_subtype, WTAP_TSPREC_USEC, asc_state, vector_asc_close);
  wth->subtype_read = vector_asc_read;
  wth->subtype_seek_read = vector_asc_seek_read;

  return WTAP_OPEN_MINE;
}

static const struct supported_block_type vector_asc_blocks_supported[] = {
    /*
     * We support packet blocks, with no comments or other options.
     */
    { WTAP_BLOCK_PACKET, MULTIPLE_BLOCKS_SUPPORTED, NO_OPTIONS_SUPPORTED }
};

static const struct file_type_subtype_info vector_asc_info = {
    "Vector ASC CAN log file", "vector-asc", "asc", NULL,
    false, BLOCKS_SUPPORTED(vector_asc_blocks_supported),
    NULL, NULL, NULL
};

void register_vector_asc(void)
{
  vector_asc_file_type_subtype = wtap_register_file_type_subtype(&vector_asc_info);
}

